import * as Cesium from 'cesium';
import { visibleHeadlines } from './headline-visibility.js';
import { labelStyle } from './news-layer.js';

export function declutterHeadlines(globe, layer) {
  let hidden = new Set();
  const remove = globe.scene.postRender.addEventListener(() => {
    const scene = globe.scene;
    const occluder = new Cesium.EllipsoidalOccluder(Cesium.Ellipsoid.WGS84, globe.camera.positionWC);
    const candidates = [];
    const singles = new Set();
    // Cesium 1.131 has no public iterator for the labels generated by EntityCluster.
    // Read only these two collections; never alter marker visibility or clustering.
    for (const collection of [layer.clustering._labelCollection, layer.clustering._clusterLabelCollection]) {
      if (!collection || collection.isDestroyed()) continue;
      for (let i = 0; i < collection.length; i++) {
        const label = collection.get(i);
        if (collection === layer.clustering._labelCollection) singles.add(label);
        if (!label.clusterShow || !label.id?.news || !occluder.isPointVisible(label.position)) continue;
        const point = label.computeScreenSpacePosition(scene);
        if (!point) continue;
        const box = Cesium.Label.getScreenSpaceBoundingBox(label, point);
        if (!Number.isFinite(box.x) || !Number.isFinite(box.width) || box.width <= 0) continue;
        const bounds = { x: box.x - 4, y: box.y - 4, width: box.width + 8, height: box.height + 8 };
        if (bounds.x + bounds.width < 0 || bounds.y + bounds.height < 0
          || bounds.x > globe.canvas.clientWidth || bounds.y > globe.canvas.clientHeight) continue;
        const item = label.id.news;
        candidates.push({ label, bounds, id: label.id.id,
          distance: Cesium.Cartesian3.distanceSquared(globe.camera.positionWC, label.position),
          timestamp: Date.parse(item.published_at) || Date.parse(item.collected_at) || 0 });
      }
    }
    const visible = visibleHeadlines(candidates);
    const nextHidden = new Set();
    for (const { label } of candidates) {
      const show = visible.has(label);
      label.fillColor = show ? labelStyle.fillColor : Cesium.Color.TRANSPARENT;
      label.outlineColor = show ? labelStyle.outlineColor : Cesium.Color.TRANSPARENT;
      if (singles.has(label)) {
        label.id.label.fillColor = label.fillColor;
        label.id.label.outlineColor = label.outlineColor;
      }
      if (!show) nextHidden.add(label);
    }
    // Restore labels that move out of the collision set, including those off screen.
    for (const label of hidden) {
      if (!nextHidden.has(label) && !label.isDestroyed()) {
        label.fillColor = labelStyle.fillColor;
        label.outlineColor = labelStyle.outlineColor;
        if (singles.has(label)) {
          label.id.label.fillColor = labelStyle.fillColor;
          label.id.label.outlineColor = labelStyle.outlineColor;
        }
      }
    }
    const changed = nextHidden.size !== hidden.size || [...nextHidden].some(label => !hidden.has(label));
    hidden = nextHidden;
    if (changed) scene.requestRender();
  });
  return remove;
}
